import{_ as t,a as n,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy","description":"学习 不定代词的后置修饰，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy","description":"学习 不定代词的后置修饰，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 不定代词的后置修饰，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin","link":"/life/english/new-concept/book-3/unit-02/lesson-026"},"next":{"text":"第三册：培养技能 · Lesson 28 Five pounds too dear","link":"/life/english/new-concept/book-3/unit-02/lesson-028"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin","link":"/life/english/new-concept/book-3/unit-02/lesson-026"},"next":{"text":"第三册：培养技能 · Lesson 28 Five pounds too dear","link":"/life/english/new-concept/book-3/unit-02/lesson-028"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-027.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-027.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-027.md"};function s(l,e,r,d,h,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-27-nothing-to-sell-and-nothing-to-buy" tabindex="-1">第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy <a class="header-anchor" href="#第三册-培养技能-·-lesson-27-nothing-to-sell-and-nothing-to-buy" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从自由生活和物质需求讨论进入不定代词。表达“不需要什么”时，要明确是完全没有需求还是只缺少某类物品。学习 nothing、anything、something 后置修饰和否定范围，同时避免用简单语法把不同生活选择浪漫化为适合所有人的答案。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>possession</td><td>/pəˈzeʃən/</td><td>n.</td><td>所有物</td><td>personal possessions</td></tr><tr><td>freedom</td><td>/ˈfriːdəm/</td><td>n.</td><td>自由</td><td>freedom of choice</td></tr><tr><td>necessity</td><td>/nəˈsesəti/</td><td>n.</td><td>必需品</td><td>basic necessities</td></tr><tr><td>independent</td><td>/ˌɪndɪˈpendənt/</td><td>adj.</td><td>独立的</td><td>remain independent</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>do without — 无某物也能应付</li><li>live on — 依靠某收入或食物生活</li></ul><h2 id="语法讲解-不定代词的后置修饰" tabindex="-1">语法讲解：不定代词的后置修饰 <a class="header-anchor" href="#语法讲解-不定代词的后置修饰" aria-label="Permalink to &quot;语法讲解：不定代词的后置修饰&quot;">​</a></h2><p>something、anything、nothing 等后面接形容词时，形容词通常后置，如 something useful。后接不定式可说明待做事项，如 nothing to buy。nothing 本身带否定意义，标准英语中通常不再加 not 构成同一否定；I don&#39;t need anything 与 I need nothing 意思接近，但后者可能更强调。not everything 表示并非全部，不等于 nothing。选择 some 或 any 不只看肯定否定，还要考虑请求、邀请和预期答案等语用条件。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We found nothing expensive in the cabin, but there was everything we needed.</p></blockquote><p>我们在小屋里没发现昂贵物品，但需要的东西一应俱全。</p><p>expensive 后置修饰 nothing；everything 后接省略宾语关系词的限定从句 we needed。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I don&#39;t need nothing 在标准书面英语里应改为 I don&#39;t need anything；not everything 不是“什么都不”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照朗读 nothing expensive 与 not everything is expensive，分别重读 nothing 和 everything，听辨“全无”与“并非全部”。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I packed nothing decorative for the trip. Everything in my bag served a clear purpose. I still carried a small first-aid kit and enough water.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句描述简朴出行准备，包含不需要的东西和必要条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>nothing 的否定范围限于装饰物，不把简朴误写为完全不做准备。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改正：We need useful something.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We need something useful.</p><p><strong>解析：</strong> 形容词置于不定代词后。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>翻译：并非所有东西都有用。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Not everything is useful.</p><p><strong>解析：</strong> 否定作用于全部范围，保留部分有用的可能。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句是否说明小屋里没有任何东西？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> 没有的是昂贵物品，必要物品却齐全。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：不定代词的后置修饰。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-026">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-028">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
